-- Phase 8: private messaging, notifications, realtime transport and email delivery history.
create table public.communication_channels(id uuid primary key default gen_random_uuid(),channel_key text not null unique,name text not null,description text,category text not null check(category in('DEPARTMENT','BROADCAST','CASE')),is_private boolean not null default false,created_by uuid not null references public.staff_profiles(id),created_at timestamptz not null default now());
create table public.communication_channel_members(channel_id uuid not null references public.communication_channels(id)on delete cascade,staff_id uuid not null references public.staff_profiles(id)on delete cascade,joined_at timestamptz not null default now(),last_read_at timestamptz,primary key(channel_id,staff_id));
create table public.communication_messages(id uuid primary key default gen_random_uuid(),sender_id uuid not null references public.staff_profiles(id),recipient_id uuid references public.staff_profiles(id),channel_id uuid references public.communication_channels(id),content text not null check(char_length(content)between 1 and 10000),tagged_student_id uuid references public.students(id),attachments jsonb not null default'[]',is_pinned boolean not null default false,edited_at timestamptz,deleted_at timestamptz,created_at timestamptz not null default now(),check((recipient_id is not null)::int+(channel_id is not null)::int=1));
create table public.communication_reactions(message_id uuid not null references public.communication_messages(id)on delete cascade,staff_id uuid not null references public.staff_profiles(id)on delete cascade,emoji text not null check(char_length(emoji)between 1 and 16),created_at timestamptz not null default now(),primary key(message_id,staff_id,emoji));
create table public.staff_notifications(id uuid primary key default gen_random_uuid(),staff_id uuid not null references public.staff_profiles(id)on delete cascade,type text not null,title text not null,body text not null,action_url text,metadata jsonb not null default'{}',read_at timestamptz,created_at timestamptz not null default now());
create table public.email_templates(id uuid primary key default gen_random_uuid(),template_key text not null unique,name text not null,category text not null,subject text not null,preheader text,body_html text not null,is_active boolean not null default true,updated_by uuid not null references public.staff_profiles(id),updated_at timestamptz not null default now());
create table public.email_automations(id uuid primary key default gen_random_uuid(),name text not null,trigger_event text not null,template_id uuid not null references public.email_templates(id),delay_hours integer not null default 0 check(delay_hours>=0),destination_filter text,is_active boolean not null default true,created_by uuid not null references public.staff_profiles(id),created_at timestamptz not null default now());
create table public.email_delivery_logs(id uuid primary key default gen_random_uuid(),template_id uuid references public.email_templates(id),automation_id uuid references public.email_automations(id),student_id uuid references public.students(id),recipient_email citext not null,recipient_name text not null,subject text not null,trigger_event text not null,status text not null default'QUEUED'check(status in('QUEUED','SENDING','DELIVERED','OPENED','CLICKED','BOUNCED','FAILED')),provider_message_id text,error_message text,queued_at timestamptz not null default now(),delivered_at timestamptz,opened_at timestamptz,clicked_at timestamptz);
create index communication_messages_recipient_idx on public.communication_messages(recipient_id,created_at desc);create index communication_messages_channel_idx on public.communication_messages(channel_id,created_at desc);create index staff_notifications_unread_idx on public.staff_notifications(staff_id,created_at desc)where read_at is null;create index email_delivery_status_idx on public.email_delivery_logs(status,queued_at);
insert into public.permissions(role,permission_name,enabled)select role,permission_name,true from unnest(enum_range(null::public.staff_role))role cross join(values('communications.use'),('notifications.view'))p(permission_name)on conflict(role,permission_name)do update set enabled=true;
insert into public.permissions(role,permission_name,enabled)select role,permission_name,true from(values('ADMIN'::public.staff_role),('DIRECTOR'),('IT_ADMIN'),('MARKETING'))r(role)cross join(values('communications.manage'),('email.manage'),('email.send'))p(permission_name)on conflict(role,permission_name)do update set enabled=true;
do $$declare t text;begin foreach t in array array['communication_channels','communication_channel_members','communication_messages','communication_reactions','staff_notifications','email_templates','email_automations','email_delivery_logs']loop execute format('alter table public.%I enable row level security',t);end loop;end$$;
create policy channel_member_read on public.communication_channels for select to authenticated using(not is_private or exists(select 1 from public.communication_channel_members m where m.channel_id=id and m.staff_id=auth.uid()));
create policy channel_members_read on public.communication_channel_members for select to authenticated using(staff_id=auth.uid()or public.has_permission('communications.manage'));
create policy messages_participant_read on public.communication_messages for select to authenticated using(deleted_at is null and(sender_id=auth.uid()or recipient_id=auth.uid()or exists(select 1 from public.communication_channel_members m where m.channel_id=communication_messages.channel_id and m.staff_id=auth.uid())));
create policy reactions_visible_message on public.communication_reactions for select to authenticated using(exists(select 1 from public.communication_messages m where m.id=message_id and(m.sender_id=auth.uid()or m.recipient_id=auth.uid()or exists(select 1 from public.communication_channel_members cm where cm.channel_id=m.channel_id and cm.staff_id=auth.uid()))));
create policy own_notifications_read on public.staff_notifications for select to authenticated using(staff_id=auth.uid());create policy own_notifications_update on public.staff_notifications for update to authenticated using(staff_id=auth.uid())with check(staff_id=auth.uid());
create policy email_admin_templates on public.email_templates for select to authenticated using(public.has_permission('email.manage'));create policy email_admin_automations on public.email_automations for select to authenticated using(public.has_permission('email.manage'));create policy email_admin_logs on public.email_delivery_logs for select to authenticated using(public.has_permission('email.manage'));
create or replace function public.send_internal_message(payload jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare mid uuid;rid uuid;cid uuid;begin if not public.has_permission('communications.use')then raise exception'Insufficient permission';end if;rid:=nullif(payload->>'recipient_id','')::uuid;cid:=nullif(payload->>'channel_id','')::uuid;if cid is not null and not exists(select 1 from communication_channel_members where channel_id=cid and staff_id=auth.uid())then raise exception'Not a channel member';end if;insert into communication_messages(sender_id,recipient_id,channel_id,content,attachments)values(auth.uid(),rid,cid,payload->>'content',coalesce(payload->'attachments','[]'))returning id into mid;if rid is not null then insert into staff_notifications(staff_id,type,title,body,action_url,metadata)select rid,'MESSAGE','New message from '||full_name,left(payload->>'content',180),'/messages',jsonb_build_object('message_id',mid)from staff_profiles where id=auth.uid();end if;return mid;end$$;
create or replace function public.toggle_message_reaction(message_uuid uuid,reaction_emoji text)returns void language plpgsql security definer set search_path=public as $$begin if not exists(select 1 from communication_messages where id=message_uuid and deleted_at is null and(sender_id=auth.uid()or recipient_id=auth.uid()or exists(select 1 from communication_channel_members where channel_id=communication_messages.channel_id and staff_id=auth.uid())))then raise exception'Message not accessible';end if;delete from communication_reactions where message_id=message_uuid and staff_id=auth.uid()and emoji=reaction_emoji;if not found then insert into communication_reactions(message_id,staff_id,emoji)values(message_uuid,auth.uid(),reaction_emoji);end if;end$$;
create or replace function public.queue_email(payload jsonb)returns uuid language plpgsql security definer set search_path=public as $$declare lid uuid;begin if not public.has_permission('email.send')then raise exception'Insufficient permission';end if;insert into email_delivery_logs(template_id,automation_id,student_id,recipient_email,recipient_name,subject,trigger_event)values(nullif(payload->>'template_id','')::uuid,nullif(payload->>'automation_id','')::uuid,nullif(payload->>'student_id','')::uuid,(payload->>'to')::citext,payload->>'to_name',payload->>'subject',payload->>'trigger_event')returning id into lid;return lid;end$$;
revoke all on function public.send_internal_message(jsonb),public.toggle_message_reaction(uuid,text),public.queue_email(jsonb)from public;grant execute on function public.send_internal_message(jsonb),public.toggle_message_reaction(uuid,text),public.queue_email(jsonb)to authenticated;
alter publication supabase_realtime add table public.communication_messages,public.communication_reactions,public.staff_notifications,public.email_delivery_logs;
